from collections import deque

def fcfs(bursts):
    t, waits = 0, []
    for b in bursts:
        waits.append(t)
        t += b
    return sum(waits) / len(waits)

def sjf(bursts):
    return fcfs(sorted(bursts))          # SJF = FCFS on jobs sorted by length

def rr(bursts, quantum):
    rem, finish = list(bursts), [0] * len(bursts)
    q, t = deque(range(len(bursts))), 0
    while q:
        i = q.popleft()
        run = min(quantum, rem[i])
        t += run
        rem[i] -= run
        if rem[i]:
            q.append(i)
        else:
            finish[i] = t
    waits = [finish[i] - bursts[i] for i in range(len(bursts))]
    return sum(waits) / len(waits)

bursts = [24, 3, 3]                       # A, B, C all arrive at t=0
assert fcfs(bursts) == 17.0               # convoy effect
assert sjf(bursts) == 3.0                 # optimal average wait
assert round(rr(bursts, 4), 2) == 5.67    # fair, fast response, middling wait
print('FCFS', fcfs(bursts), '| SJF', sjf(bursts), '| RR q=4', round(rr(bursts, 4), 2))

from collections import deque

def fifo_faults(frames, refs):
    q, resident, faults = deque(), set(), 0
    for r in refs:
        if r not in resident:
            faults += 1
            if len(resident) == frames:
                resident.discard(q.popleft())     # evict the longest-resident page
            q.append(r); resident.add(r)
    return faults

def lru_faults(frames, refs):
    stack, faults = [], 0                          # most-recent at the end
    for r in refs:
        if r in stack:
            stack.remove(r)                        # touch -> move to most-recent
        else:
            faults += 1
            if len(stack) == frames:
                stack.pop(0)                       # evict least-recently-used
        stack.append(r)
    return faults

refs = [1, 2, 3, 4, 1, 2, 5, 1, 2, 3, 4, 5]

assert fifo_faults(3, refs) == 9
assert fifo_faults(4, refs) == 10      # MORE frames, MORE faults: Belady's anomaly
assert lru_faults(3, refs) == 10
assert lru_faults(4, refs) == 8        # LRU is a stack algorithm: more frames never hurt
print('FIFO 3->9, 4->10 (anomaly!) | LRU 3->10, 4->8')
